<?php
declare(strict_types=1); namespace App\IdentityAccess\Application\Command\RemovePermissionFromRole; use App\IdentityAccess\Domain\Exception\RoleNotFound; use App\IdentityAccess\Domain\Repository\RoleRepository; use App\IdentityAccess\Domain\ValueObject\PermissionId; use App\IdentityAccess\Domain\ValueObject\RoleId; #[\Symfony\Component\Messenger\Attribute\AsMessageHandler]
final readonly class RemovePermissionFromRoleHandler { public function __construct(private RoleRepository $roles){} public function __invoke(RemovePermissionFromRoleCommand $c):void{$role=$this->roles->findById(RoleId::fromString($c->roleId));if(!$role)throw new RoleNotFound($c->roleId);$role->removePermission(PermissionId::fromString($c->permissionId),new \DateTimeImmutable());$this->roles->save($role);} }
